window.EXAM_BANK = [{"id":"1-1","chapter":1,"chapterTitle":"第1章 概论","type":"单项选择","question":"反映地理事物位置、属性及其相互关系的信息称为","options":["地理信息","纯文本编码","计算机指令","随机噪声"],"correct":"A","answer":"地理信息包含空间位置及相关属性等信息。"},{"id":"1-2","chapter":1,"chapterTitle":"第1章 概论","type":"判断并说明","question":"GIS只是一套硬件设备。","options":[],"correct":"错误","answer":"错误。GIS还包括软件、空间数据、地学模型及人员等。"},{"id":"1-3","chapter":1,"chapterTitle":"第1章 概论","type":"填空","question":"GIS的空间分析依赖对空间位置及其________的表达。","options":[],"correct":"","answer":"填空：关系。"},{"id":"1-4","chapter":1,"chapterTitle":"第1章 概论","type":"名词解释","question":"地理信息系统。","options":[],"correct":"","answer":"GIS 以地学原理为依托，在计算机软硬件支持下，对空间数据进行采集、处理、存储、管理、分析、建模与显示，以支持管理、规划和决策。教材指出它兼有学科和技术性质。参见教材 1.1.3，印刷第 9 页。"},{"id":"1-5","chapter":1,"chapterTitle":"第1章 概论","type":"简答","question":"简述GIS的主要组成及各自作用。","options":[],"correct":"","answer":"硬件提供运行环境；软件提供功能；空间数据是处理对象和基础；地学模型支撑分析；人员负责建设、维护与应用。"},{"id":"1-6","chapter":1,"chapterTitle":"第1章 概论","type":"应用与计算","question":"给校园选址建设新服务点，说明GIS可发挥的作用。","options":[],"correct":"","answer":"采集道路、人口与现有设施数据；统一参考与质量检查；分析服务范围与可达性；比较候选地并制图表达。"},{"id":"1-7","chapter":1,"chapterTitle":"第1章 概论","type":"单项选择","question":"GIS区别于一般信息系统的突出能力是","options":["空间分析","文字编辑","电子邮件收发","格式转换"],"correct":"A","answer":"空间分析利用位置和空间关系，支持地理问题的研究。"},{"id":"1-8","chapter":1,"chapterTitle":"第1章 概论","type":"单项选择","question":"以下哪项属于空间数据的属性信息","options":["道路名称","道路几何形状","道路位置坐标","道路与河流交点位置"],"correct":"A","answer":"道路名称描述道路的属性，其他选项主要涉及空间特征。"},{"id":"1-9","chapter":1,"chapterTitle":"第1章 概论","type":"单项选择","question":"描述数据来源、质量和坐标参考的资料通常称为","options":["元数据","地图比例尺","地形坡度","地理围栏"],"correct":"A","answer":"元数据描述数据本身及其管理信息。"},{"id":"1-10","chapter":1,"chapterTitle":"第1章 概论","type":"判断并说明","question":"地理信息具有空间定位特征。","options":[],"correct":"正确","answer":"正确。地理信息与地理位置相关联。"},{"id":"1-11","chapter":1,"chapterTitle":"第1章 概论","type":"判断并说明","question":"GIS分析结果的可靠性完全不受输入数据质量影响。","options":[],"correct":"错误","answer":"错误。输入误差会影响分析结果。"},{"id":"1-12","chapter":1,"chapterTitle":"第1章 概论","type":"判断并说明","question":"GIS既可以管理空间位置，也可以管理与空间对象相关的属性。","options":[],"correct":"正确","answer":"正确。两者需要有效关联。"},{"id":"1-13","chapter":1,"chapterTitle":"第1章 概论","type":"简答","question":"区分数据与信息。","options":[],"correct":"","answer":"数据是对事物和环境的定性或定量原始记录；信息体现数据的含义和对数据的解释。数据是信息的载体。参见教材 1.1.1，印刷第 7 页。"},{"id":"1-14","chapter":1,"chapterTitle":"第1章 概论","type":"简答","question":"地理数据和地理信息有什么联系？","options":[],"correct":"","answer":"地理数据是记录地理现象及其空间位置、属性等的载体；经处理和解释可形成有用的地理信息。"},{"id":"1-15","chapter":1,"chapterTitle":"第1章 概论","type":"简答","question":"列举GIS的主要基本功能。","options":[],"correct":"","answer":"教材列出六项：数据采集；数据编辑与处理；数据存储、组织与管理；空间查询与空间分析；数据输出与可视化表达；应用模型与系统开发。参见教材 1.3.2，印刷第 17—20 页。"},{"id":"1-16","chapter":1,"chapterTitle":"第1章 概论","type":"简答","question":"GIS与普通管理信息系统有何主要区别？","options":[],"correct":"","answer":"GIS突出空间位置、形状和空间关系的管理与分析；普通管理信息系统通常以非空间业务信息处理为主，两者可以集成。"},{"id":"1-17","chapter":1,"chapterTitle":"第1章 概论","type":"简答","question":"空间数据在GIS中发挥什么作用？","options":[],"correct":"","answer":"它是空间对象、现象和关系的数字化表达，也是查询、分析、建模及地图表达的基础。"},{"id":"1-18","chapter":1,"chapterTitle":"第1章 概论","type":"简答","question":"地学模型在GIS应用中的作用是什么？","options":[],"correct":"","answer":"以一定规则表达地理过程或关系，使GIS能够对空间现象进行解释、模拟或预测。"},{"id":"1-19","chapter":1,"chapterTitle":"第1章 概论","type":"简答","question":"遥感与GIS如何相互配合？","options":[],"correct":"","answer":"遥感可提供地表观测数据；GIS对遥感结果与其他空间数据进行集成、管理、分析和表达。"},{"id":"1-20","chapter":1,"chapterTitle":"第1章 概论","type":"简答","question":"选择一个GIS应用，说明输入、处理和输出。","options":[],"correct":"","answer":"例如设施选址：输入道路、人口和设施数据；进行可达性与服务范围分析；输出候选位置及专题地图。"},{"id":"1-21","chapter":1,"chapterTitle":"第1章 概论","type":"简答","question":"为什么GIS项目需要人员参与？","options":[],"correct":"","answer":"需求分析、数据采集与审核、模型选择、结果解释和系统维护都需要人员组织实施。"},{"id":"2-1","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"单项选择","question":"关于地图投影，下列说法正确的是","options":["任何投影都无变形","投影将曲面上的位置按一定数学法则表示到平面","经纬度与平面坐标完全相同","所有地图必须使用同一种投影"],"correct":"B","answer":"球面或椭球面展开到平面一般会产生变形。"},{"id":"2-2","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"判断并说明","question":"等角投影同时保证任意区域面积完全不变。","options":[],"correct":"错误","answer":"错误。等角保持局部角度，但一般不保持面积。"},{"id":"2-3","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"填空","question":"在地图上，距离的缩小程度常用________表示。","options":[],"correct":"","answer":"填空：比例尺。"},{"id":"2-4","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"名词解释","question":"地图投影。","options":[],"correct":"","answer":"按照一定数学法则，将地球椭球面或球面上的点表示到平面上的方法。"},{"id":"2-5","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"简答","question":"比较地理坐标和投影平面坐标。","options":[],"correct":"","answer":"地理坐标通常用经纬度描述椭球面位置；投影坐标通过投影变换在平面上表示位置，常用线性单位。二者均须明确相关参考。"},{"id":"2-6","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"应用与计算","question":"地图比例尺为1:50000，图上2厘米对应实地多少米？","options":[],"correct":"","answer":"实地距离为2×50000厘米，即100000厘米，等于1000米；此处假设比例尺适用且量距无误。"},{"id":"2-7","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"单项选择","question":"高斯—克吕格投影属于","options":["横轴等角圆柱投影","等积方位投影","正轴等距圆锥投影","无变形投影"],"correct":"A","answer":"其投影方式为横轴等角圆柱投影。"},{"id":"2-8","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"单项选择","question":"地图比例尺为1:10000，图上1厘米代表实地","options":["100米","10米","1000米","1米"],"correct":"A","answer":"1厘米乘10000为100米。"},{"id":"2-9","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"单项选择","question":"同一范围内，栅格像元边长变为原来一半，理论像元数约为原来的","options":["4倍","2倍","一半","不变"],"correct":"A","answer":"行列数各约增加一倍，因此像元数约为四倍。"},{"id":"2-10","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"判断并说明","question":"同一投影一定能同时消除所有长度、面积和角度变形。","options":[],"correct":"错误","answer":"错误。通常只能按特定性质控制某些变形。"},{"id":"2-11","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"判断并说明","question":"经纬度的数值相同，在不同大地基准下仍可能对应不同地面位置。","options":[],"correct":"正确","answer":"正确。坐标解释依赖所采用的大地基准。"},{"id":"2-12","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"判断并说明","question":"比例尺1:10000比1:100000更大。","options":[],"correct":"正确","answer":"正确。前者的分母较小，比例尺数值较大。"},{"id":"2-13","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"简答","question":"什么是大地水准面？","options":[],"correct":"","answer":"大地水准面是与重力场有关的特定重力等位面，可理解为与平均海面接近并向大陆内部延伸的参考面。实际平均海面与大地水准面存在差异；高程基准还涉及水准原点。参见教材 2.1.1、2.1.3，印刷第 29、35 页。"},{"id":"2-14","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"简答","question":"地球椭球为什么适合作为测量计算的参考面？","options":[],"correct":"","answer":"它是规则的数学曲面，能够近似地球形状，便于建立坐标及进行测量和投影计算。"},{"id":"2-15","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"简答","question":"按变形性质地图投影可如何分类？","options":[],"correct":"","answer":"教材按变形性质讨论等角投影、等面积投影，以及任意投影和等距投影。等距应明确保持距离的方向或范围，并不意味着任意两点间距离都不变。参见教材 2.2.2，印刷第 40 页。"},{"id":"2-16","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"简答","question":"如何根据地图用途选择投影？","options":[],"correct":"","answer":"综合考虑区域位置、形状和范围，以及对角度、面积、距离等精度的要求，选用适合的投影及参数。"},{"id":"2-17","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"简答","question":"坐标转换与地图投影是什么关系？","options":[],"correct":"","answer":"投影是曲面位置和平面位置之间的数学映射；坐标转换还包括不同参考框架或不同坐标表达之间的变换。"},{"id":"2-18","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"简答","question":"分辨率和比例尺为什么不能简单等同？","options":[],"correct":"","answer":"比例尺表示图上与实地距离的比值；分辨率表示能够区分或表达空间细节的程度，两者含义不同但都影响细节表达。"},{"id":"2-19","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"简答","question":"高程基准与平面坐标参考为什么都需要说明？","options":[],"correct":"","answer":"高程基准涉及水准基面和水准原点，用以统一高程起算；平面坐标还需明确相关地理坐标参考和投影规则。二者不一致时可能影响数据叠加和高程比较。参见教材 2.1.2—2.1.3，印刷第 31、35 页。"},{"id":"2-20","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"计算","question":"某区域宽2千米，使用20米像元表示，忽略边缘情况，横向约有多少列？","options":[],"correct":"","answer":"2000除以20，约100列。"},{"id":"2-21","chapter":2,"chapterTitle":"第2章 地理空间数学基础","type":"计算","question":"图上距离3厘米，实地距离1.5千米，求比例尺。","options":[],"correct":"","answer":"1.5千米等于150000厘米，比例尺为3:150000，即1:50000。"},{"id":"3-1","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"单项选择","question":"适宜表达连续变化的高程现象的概念模型是","options":["场模型","单纯表格模型","人员模型","文件目录模型"],"correct":"A","answer":"场模型将属性看作空间位置的函数，适合表达连续变化现象。"},{"id":"3-2","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"判断并说明","question":"空间数据模型和数据结构完全是同一层次的概念。","options":[],"correct":"错误","answer":"错误。教材将空间抽象分为概念、逻辑和物理模型，通常所称空间数据模型指逻辑模型；空间数据结构是逻辑模型映射为物理模型的中间媒介。参见教材 3.1.2，印刷第 56 页。"},{"id":"3-3","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"填空","question":"地理空间抽象中，离散事物可用________模型表达。","options":[],"correct":"","answer":"填空：对象。"},{"id":"3-4","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"名词解释","question":"空间数据模型。","options":[],"correct":"","answer":"空间数据模型是对现实地理世界抽象描述的模型。教材指出，通常所称的空间数据模型指空间数据的逻辑模型；数据结构则是逻辑模型映射为物理模型的中间媒介。参见教材 3.1.2，印刷第 56 页。"},{"id":"3-5","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"简答","question":"比较对象模型与场模型。","options":[],"correct":"","answer":"对象模型突出具有边界、身份和属性的离散实体；场模型强调属性在空间中连续或按位置分布；选择取决于研究对象和尺度。"},{"id":"3-6","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"应用与计算","question":"设计一个公交站点与道路网络的数据模型，指出主要对象及关系。","options":[],"correct":"","answer":"站点用点、道路用线表达；赋予编号和名称等属性；记录线路的连接关系及站点与道路的关联。"},{"id":"3-7","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"单项选择","question":"描述河网中水流连接关系时，优先考虑","options":["网络模型","纯文字文档","柱状图","颜色表"],"correct":"A","answer":"网络模型强调结点和连接关系。"},{"id":"3-8","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"单项选择","question":"一宗地与另一宗地共享边界，主要体现","options":["拓扑关系","光谱关系","语音关系","文件大小关系"],"correct":"A","answer":"共享边界可体现空间邻接。"},{"id":"3-9","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"单项选择","question":"描述数据库中对象类别及其联系，通常首先建立","options":["概念模型","打印机驱动","显示器配置","照片压缩率"],"correct":"A","answer":"概念模型面向现实世界，表达对象及关系。"},{"id":"3-10","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"判断并说明","question":"同一现实地理现象在不同研究目标下可以采用不同抽象方式。","options":[],"correct":"正确","answer":"正确。抽象取决于研究目标、尺度和数据条件。"},{"id":"3-11","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"判断并说明","question":"场模型只能表达道路交叉口等离散结点。","options":[],"correct":"错误","answer":"错误。场模型侧重表达属性在空间中的分布。"},{"id":"3-12","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"判断并说明","question":"时空模型需要关注对象或现象随时间发生的变化。","options":[],"correct":"正确","answer":"正确。它同时涉及空间和时间信息。"},{"id":"3-13","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"简答","question":"现实世界到空间数据表达通常经历什么过程？","options":[],"correct":"","answer":"通过观察与抽象建立概念模型，再设计逻辑模型并通过物理存储实现。"},{"id":"3-14","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"简答","question":"对象模型中，一个空间对象通常包括哪些信息？","options":[],"correct":"","answer":"对象标识、空间位置与形状、属性信息以及与其他对象的关系等。"},{"id":"3-15","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"简答","question":"什么是空间实体？","options":[],"correct":"","answer":"具有一定位置和空间范围、能够作为研究对象加以识别的地理事物或现象。"},{"id":"3-16","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"简答","question":"区分空间属性数据与几何数据。","options":[],"correct":"","answer":"几何数据描述位置、形状和范围；属性数据描述对象的名称、类别、数量等非几何特征。"},{"id":"3-17","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"简答","question":"举例说明空间拓扑关系、方向关系和距离关系。","options":[],"correct":"","answer":"教材称为拓扑关系、顺序关系和度量关系。例如相邻宗地体现邻接；学校位于医院以北体现顺序或方位；两点相距 500 米体现度量关系。参见教材 3.4.2，印刷第 73 页。"},{"id":"3-18","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"简答","question":"网络模型的结点和边各代表什么？","options":[],"correct":"","answer":"结点表示网络中的端点、交点或设施；边表示连接结点的道路、管线等，具体含义依应用定义。"},{"id":"3-19","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"简答","question":"空间对象为什么需要唯一标识？","options":[],"correct":"","answer":"标识便于关联几何与属性、更新对象、维护引用并避免混淆。"},{"id":"3-20","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"简答","question":"逻辑数据模型与物理数据模型有什么区别？","options":[],"correct":"","answer":"逻辑模型定义数据类别、结构与关系；物理模型进一步确定存储、索引等实现方式。"},{"id":"3-21","chapter":3,"chapterTitle":"第3章 空间数据模型","type":"简答","question":"土地覆盖变化研究中为什么需要时间维度？","options":[],"correct":"","answer":"时间信息可区分不同时期状态，支持变化识别、过程分析及对比。"},{"id":"4-1","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"单项选择","question":"游程长度编码主要用于","options":["压缩连续相同值的栅格","计算地图投影","设置数据库权限","文字校对"],"correct":"A","answer":"游程编码以值及连续长度表示相同值段。"},{"id":"4-2","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"判断并说明","question":"拓扑关系必须依赖具体坐标数值的精确大小才能表达。","options":[],"correct":"错误","answer":"错误。邻接、关联、包含等拓扑关系侧重连接和相对关系。"},{"id":"4-3","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"填空","question":"栅格数据通常由按行列组织的________构成。","options":[],"correct":"","answer":"填空：像元。"},{"id":"4-4","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"名词解释","question":"拓扑关系。","options":[],"correct":"","answer":"空间拓扑关系描述空间图形在连续变形时保持不变的关系。教材列出邻接、关联、包含和连通四类。参见教材 3.4.2，印刷第 73—74 页。"},{"id":"4-5","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"简答","question":"比较矢量与栅格结构的主要优缺点。","options":[],"correct":"","answer":"矢量以坐标表达几何，便于表示离散对象和边界，但建立维护拓扑需要额外工作；栅格按规则单元组织，便于逐格运算和叠置，但边界表达受像元大小和赋值规则影响。数据精度还取决于来源与处理过程。参见教材第 4 章。"},{"id":"4-6","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"应用与计算","question":"一行栅格为1、1、1、2、2、3，按“值：长度”写出游程编码。","options":[],"correct":"","answer":"1：3；2：2；3：1。应事先约定按行扫描及游程的记录格式。"},{"id":"4-7","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"单项选择","question":"四叉树编码的基本思想是","options":["递归划分四个子区","仅存储文本行","随机划分三个子区","只保存坐标原点"],"correct":"A","answer":"对不均一区域继续分成四个子区。"},{"id":"4-8","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"单项选择","question":"拓扑结构中的弧段通常连接","options":["结点","图例","图幅标题","色标"],"correct":"A","answer":"弧段通过起止结点建立连接。"},{"id":"4-9","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"单项选择","question":"栅格化时像元越粗，通常越可能","options":["丢失小尺度细节","无限提高边界精度","保证不存在混合像元","消除空间误差"],"correct":"A","answer":"较粗像元可能无法表达较小或狭窄的对象。"},{"id":"4-10","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"判断并说明","question":"矢量转栅格后，结果不受像元大小影响。","options":[],"correct":"错误","answer":"错误。像元大小直接影响细节和边界表达。"},{"id":"4-11","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"判断并说明","question":"共享边界仅存储一次是拓扑结构可能具有的优点。","options":[],"correct":"正确","answer":"正确。利用共享边界有助于减少重复并维护邻接关系。"},{"id":"4-12","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"判断并说明","question":"游程编码通常对空间分布高度随机的数据压缩效果最好。","options":[],"correct":"错误","answer":"错误。相同值连续段较短时压缩优势往往减弱。"},{"id":"4-13","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"简答","question":"实体式矢量结构和拓扑结构有何区别？","options":[],"correct":"","answer":"实体数据结构以多边形等实体为单位组织边界坐标，不直接记录实体间的拓扑关系，公共边界可能重复；拓扑结构通过点、弧段、面等的关系组织数据，可支持邻接和连通等分析。参见教材 4.1.1—4.1.2，印刷第 78—83 页。"},{"id":"4-14","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"简答","question":"什么是完全栅格编码？","options":[],"correct":"","answer":"完全栅格结构把栅格视为数据矩阵，按照约定顺序逐个记录单元值，不作压缩；教材介绍基于像元、基于层和基于面域三种组织方式。参见教材 4.2.1，印刷第 86—87 页。"},{"id":"4-15","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"简答","question":"四叉树编码何时继续划分？","options":[],"correct":"","answer":"当前区域不满足预定的均一或停止条件时继续划分；实际规则由编码方案确定。"},{"id":"4-16","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"简答","question":"说明链码表达边界的基本思路。","options":[],"correct":"","answer":"指定起点和方向编码规则，依次记录边界相邻步进方向；解码需知道起点、方向定义及分辨率。"},{"id":"4-17","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"简答","question":"栅格矢量化和矢量栅格化分别做什么？","options":[],"correct":"","answer":"前者从栅格中提取点、线或面；后者依据规则将矢量对象赋值到栅格单元。"},{"id":"4-18","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"简答","question":"什么是影像金字塔？","options":[],"correct":"","answer":"将影像逐级降采样形成多分辨率层级，以适应不同显示比例并提高浏览效率。"},{"id":"4-19","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"简答","question":"Voronoi图的基本划分原则是什么？","options":[],"correct":"","answer":"每个区域内的点到对应生成点的距离不大于到其他生成点的距离。"},{"id":"4-20","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"简答","question":"TIN为什么可适应地形变化？","options":[],"correct":"","answer":"可按地形复杂程度不规则布点，在关键地形部位增加节点，平坦区域适当减少。"},{"id":"4-21","chapter":4,"chapterTitle":"第4章 空间数据结构","type":"计算","question":"一行栅格为2、2、2、2、5、5、1，写出值与长度编码。","options":[],"correct":"","answer":"2:4，5:2，1:1；假设从左到右扫描。"},{"id":"5-1","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"单项选择","question":"空间索引的主要作用是","options":["加快空间对象候选检索","改变地球椭球","保证数据绝无错误","替代全部属性表"],"correct":"A","answer":"空间索引用空间范围等结构缩小候选集，之后通常还需精确判断。"},{"id":"5-2","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"判断并说明","question":"建立空间索引后，空间查询永远不需要再进行精确几何判断。","options":[],"correct":"错误","answer":"错误。包围盒等索引常产生候选结果，还需进行精确关系判断。"},{"id":"5-3","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"填空","question":"空间数据库设计通常包含概念设计、逻辑设计与________等阶段。","options":[],"correct":"","answer":"填空：物理设计。"},{"id":"5-4","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"名词解释","question":"空间索引。","options":[],"correct":"","answer":"为提高空间对象检索效率，按其空间位置、范围或空间关系建立的辅助数据结构。"},{"id":"5-5","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"简答","question":"说明空间数据库设计的基本步骤。","options":[],"correct":"","answer":"教材列出八项：确定业务需求与目标信息产品；确定主要数据专题；指定比例范围及空间表示；分解为地理数据集合；定义属性表结构与行为；定义空间行为、关系和完整性规则；构建原型并测试优化；记录设计。参见教材 5.2.2，印刷第 107—108 页。"},{"id":"5-6","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"应用与计算","question":"对百万条道路查询某行政区内的道路，说明查询流程。","options":[],"correct":"","answer":"统一坐标参考；借空间索引按区域范围获取候选道路；用真实几何关系筛选；按需要检查属性并输出。"},{"id":"5-7","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"单项选择","question":"关系数据库中用于唯一识别记录的字段称为","options":["主键","颜色表","比例尺","图廓"],"correct":"A","answer":"主键用于唯一标识一条记录。"},{"id":"5-8","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"单项选择","question":"R树索引主要利用对象的","options":["最小外接矩形等空间范围","字体颜色","文件名称长度","输入顺序"],"correct":"A","answer":"R树使用分层的包围矩形组织空间对象。"},{"id":"5-9","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"单项选择","question":"将道路空间表和道路属性表关联，最关键的是","options":["稳定且匹配的标识字段","表格的显示颜色","打印纸大小","文件创建顺序"],"correct":"A","answer":"一致的标识字段支持准确关联。"},{"id":"5-10","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"判断并说明","question":"空间索引的性能与空间数据分布和查询范围有关。","options":[],"correct":"正确","answer":"正确。索引结构及对象分布会影响候选对象数量。"},{"id":"5-11","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"判断并说明","question":"关系表中出现重复主键仍可无歧义标识不同记录。","options":[],"correct":"错误","answer":"错误。主键必须唯一且不可为空。"},{"id":"5-12","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"判断并说明","question":"数据库备份可以替代数据质量检查。","options":[],"correct":"错误","answer":"错误。备份主要保障恢复，不能证明数据正确。"},{"id":"5-13","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"简答","question":"空间数据库有哪些主要组成内容？","options":[],"correct":"","answer":"包括空间对象的几何、属性、空间关系及相关元数据，并由数据库管理系统及相关机制进行管理。"},{"id":"5-14","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"简答","question":"空间数据库设计为什么要先做需求分析？","options":[],"correct":"","answer":"明确用户、对象、查询分析任务、精度和更新要求，为模型和实现选择提供依据。"},{"id":"5-15","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"简答","question":"分层组织空间数据有什么好处？","options":[],"correct":"","answer":"可按主题管理对象，方便显示、查询和叠置，也利于权限及更新管理。"},{"id":"5-16","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"简答","question":"空间数据库引擎的作用是什么？","options":[],"correct":"","answer":"在应用与数据库之间提供空间数据存取、管理和查询等能力，具体功能随系统实现不同。"},{"id":"5-17","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"简答","question":"空间查询和属性查询有什么不同？","options":[],"correct":"","answer":"空间查询依据位置、范围或空间关系筛选对象；属性查询依据字段值及逻辑条件筛选，两者可组合。"},{"id":"5-18","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"简答","question":"什么是最小外接矩形？","options":[],"correct":"","answer":"与坐标轴平行并能够包围目标几何对象的最小矩形，常用于空间索引的初步筛选。"},{"id":"5-19","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"简答","question":"为什么空间索引得到的候选结果可能包含不符合条件的对象？","options":[],"correct":"","answer":"外接矩形只是几何对象的近似表达，相交的外接矩形对应的真实几何未必相交。"},{"id":"5-20","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"简答","question":"什么是数据一致性？举空间数据例子。","options":[],"correct":"","answer":"数据之间应满足约定规则；例如宗地边界、面积属性及相邻宗地拓扑关系应相互协调。"},{"id":"5-21","chapter":5,"chapterTitle":"第5章 空间数据组织与管理","type":"简答","question":"设计道路数据表时应考虑哪些内容？","options":[],"correct":"","answer":"明确对象标识、几何类型、道路名称等级等字段；设置坐标参考、约束、索引、更新及质量规则。"},{"id":"6-1","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"单项选择","question":"土地利用分类图进行重采样，较适合保持类别代码的方法是","options":["最近邻法","双线性内插","三次卷积","任意求平均"],"correct":"A","answer":"最近邻选取已有像元值，避免生成无意义的中间类别代码。"},{"id":"6-2","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"判断并说明","question":"所有几何纠正都能自动消除原始数据中的一切误差。","options":[],"correct":"错误","answer":"错误。纠正受控制点、模型及原始测量质量等限制。"},{"id":"6-3","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"填空","question":"几何纠正过程中，利用已知位置的________建立变换关系。","options":[],"correct":"","answer":"填空：控制点。"},{"id":"6-4","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"名词解释","question":"空间数据重采样。","options":[],"correct":"","answer":"栅格在几何纠正、旋转、投影变换或调整分辨率后，输出格网位置可能不与原格网重合，需要根据原栅格估算输出像元值，这一过程称为重采样。参见教材 6.4.3，印刷第 152 页。"},{"id":"6-5","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"简答","question":"比较最近邻、双线性内插与三次卷积。","options":[],"correct":"","answer":"最近邻选取最近原像元值，通常适用于类别数据；双线性利用邻近四个像元按相对位置加权；双三次卷积利用较大邻域估计数值。方法选择还需考虑数据性质、精度和 NoData 规则。参见教材 6.4.3，印刷第 152—153 页。"},{"id":"6-6","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"应用与计算","question":"将不同来源道路图叠加前，应检查并处理什么？","options":[],"correct":"","answer":"检查坐标参考、投影与单位；必要时转换并校正；检查精度、时间、边界接合及拓扑错误，记录元数据。"},{"id":"6-7","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"单项选择","question":"以下哪种重采样通常不产生新类别编码","options":["最近邻","双线性","三次卷积","邻域平均"],"correct":"A","answer":"最近邻直接选用某个原像元值。"},{"id":"6-8","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"单项选择","question":"控制点用于几何纠正时，应尽量","options":["分布均匀且位置可靠","全部集中在一角","只选择模糊目标","忽略坐标参考"],"correct":"A","answer":"应选择可靠、容易识别的同名控制点，并在研究区合理分布，以建立和求解变换模型；应另用未参与拟合的独立检查点评价精度。参见教材 6.4.1，印刷第 148—149 页。"},{"id":"6-9","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"单项选择","question":"两幅相邻图幅拼接前，应重点检查","options":["坐标参考及接边一致性","文件名长度","屏幕亮度","文档页边距"],"correct":"A","answer":"坐标不一致或边界错位会影响拼接。"},{"id":"6-10","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"判断并说明","question":"控制点越多且分布越好，误差就必定为零。","options":[],"correct":"错误","answer":"错误。数据噪声、模型偏差等仍可能存在。"},{"id":"6-11","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"判断并说明","question":"栅格数据进行坐标变换时，往往需要重新确定输出像元值。","options":[],"correct":"正确","answer":"正确。输出格网位置一般不能与原格网完全对应。"},{"id":"6-12","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"判断并说明","question":"扫描地图获取图像后，不经处理就一定具备正确的地理坐标。","options":[],"correct":"错误","answer":"错误。通常需要配准或几何纠正，并核实坐标参考。"},{"id":"6-13","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"简答","question":"空间数据常见来源有哪些？","options":[],"correct":"","answer":"可包括已有地图、遥感影像、野外测量、卫星定位、统计资料及已有数据库等。"},{"id":"6-14","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"简答","question":"数字化采集与扫描矢量化有何区别？","options":[],"correct":"","answer":"前者通常沿地图要素逐点或逐线采集坐标；后者先获取栅格影像，再人工或自动提取矢量要素。"},{"id":"6-15","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"简答","question":"几何纠正的一般步骤是什么？","options":[],"correct":"","answer":"明确参考资料与坐标系统；选择分布合理的同名控制点；选择并求解适合的变换模型；检查拟合残差并使用独立检查点评价。对栅格影像生成输出格网时通常还需重采样；对矢量数据不应一概要求像元重采样。参见教材 6.4.1、6.4.3，印刷第 148—153 页。"},{"id":"6-16","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"简答","question":"控制点和检查点的用途有何区别？","options":[],"correct":"","answer":"控制点用于建立变换模型；独立检查点用于评价模型在未知点的精度。"},{"id":"6-17","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"简答","question":"数据接边可能出现哪些问题？","options":[],"correct":"","answer":"边界位置错位、属性编码不一致、线段未连接或重复，以及不同时期内容不一致。"},{"id":"6-18","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"简答","question":"空间数据质量通常可从哪些方面评价？","options":[],"correct":"","answer":"可考虑位置精度、属性精度、完整性、逻辑一致性、时间现势性和来源等。"},{"id":"6-19","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"简答","question":"元数据应记录哪些与成果使用有关的信息？","options":[],"correct":"","answer":"可记录数据来源、坐标参考、采集时间、精度、处理过程、字段说明和更新情况。"},{"id":"6-20","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"简答","question":"为什么遥感连续数值影像和土地利用类别图的重采样方法可能不同？","options":[],"correct":"","answer":"连续值可考虑平滑插值；类别编码不宜产生中间值，通常采用最近邻。"},{"id":"6-21","chapter":6,"chapterTitle":"第6章 空间数据采集与处理","type":"简答","question":"如何检查道路矢量化结果？","options":[],"correct":"","answer":"检查漏采、重复、断头、过冲、连接关系、属性完整性和与参考数据的位置偏差。"},{"id":"7-1","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"单项选择","question":"求道路周边一定距离范围宜使用","options":["缓冲区分析","文字检索","数据库备份","打印预览"],"correct":"A","answer":"缓冲区分析构建距离指定空间对象一定范围内的区域。"},{"id":"7-2","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"判断并说明","question":"两个图层坐标系不一致时，可直接将其坐标数值当作同一坐标系进行叠置。","options":[],"correct":"错误","answer":"错误。应先核实参考并进行适当变换，保证空间位置可比较。"},{"id":"7-3","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"填空","question":"将多个图层的空间与属性信息组合分析称为________。","options":[],"correct":"","answer":"填空：叠置分析。"},{"id":"7-4","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"名词解释","question":"缓冲区分析。","options":[],"correct":"","answer":"缓冲区分析按照选定的距离与侧别等规则，在点、线或面对象周围建立一定范围，用于确定邻近关系及后续空间分析；面缓冲需明确内侧、外侧和边界约定。参见教材 7.4，印刷第 185—190 页。"},{"id":"7-5","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"简答","question":"说明叠置分析的一般过程。","options":[],"correct":"","answer":"明确分析目标和输入数据；检查并统一必要的空间参考、精度与网格规则；选择交集、差集等叠置方式；组合空间位置与属性；检查边界、小图斑、NoData 和结果。参见教材 7.3，印刷第 178—184 页。"},{"id":"7-6","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"应用与计算","question":"拟选择距道路500米以内且在建设用地范围内的位置，设计流程。","options":[],"correct":"","answer":"统一投影和距离单位；对道路生成500米缓冲区；与建设用地图层求交；结合其他限制及精度复核。"},{"id":"7-7","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"单项选择","question":"分析道路上最短行驶距离应优先使用","options":["网络分析","颜色反相","地图裁剪","格式转换"],"correct":"A","answer":"网络分析基于连接关系和边阻抗求解路径。"},{"id":"7-8","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"单项选择","question":"获得两个面图层共同覆盖的区域可使用","options":["交集叠置","图像旋转","图例重排","数据压缩"],"correct":"A","answer":"交集保留同时位于两个输入对象内的区域。"},{"id":"7-9","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"单项选择","question":"计算医院周围步行服务范围，除距离外还应考虑","options":["道路连通性与通行条件","文件名","符号字体","纸张克重"],"correct":"A","answer":"真实可达性依赖可通行网络及其成本。"},{"id":"7-10","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"判断并说明","question":"欧氏距离缓冲区必然等于沿道路可达范围。","options":[],"correct":"错误","answer":"错误。道路连通、障碍物和绕行会造成差异。"},{"id":"7-11","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"判断并说明","question":"面状缓冲区可用于表示距对象一定距离内的空间范围。","options":[],"correct":"正确","answer":"正确。距离设定和单位应与坐标系匹配。"},{"id":"7-12","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"判断并说明","question":"空间查询和复杂空间分析完全相同。","options":[],"correct":"错误","answer":"错误。查询主要筛选对象；分析通常进一步运算、建模或综合多个空间关系。"},{"id":"7-13","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"简答","question":"空间分析有什么核心特征？","options":[],"correct":"","answer":"利用空间位置、形态和关系，通过运算或模型提取信息，支持地理问题分析。"},{"id":"7-14","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"简答","question":"点、线、面对象缓冲区的含义有何共同点？","options":[],"correct":"","answer":"共同点是依据距离规则构建研究对象附近的区域；点、线、面生成的几何形态不同。线可按规则选择侧别，面可构建内侧或外侧范围，并需明确边界是否计入。参见教材 7.4.1，印刷第 185—188 页。"},{"id":"7-15","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"简答","question":"缓冲区分析时为什么需要关注坐标单位？","options":[],"correct":"","answer":"缓冲距离必须与计算坐标的单位及投影适用范围一致，否则距离可能不正确。"},{"id":"7-16","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"简答","question":"交集与并集叠置有什么区别？","options":[],"correct":"","answer":"交集保留共同覆盖部分；并集形成输入面覆盖范围的组合并保留各区域的来源信息。"},{"id":"7-17","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"简答","question":"网络分析中的阻抗可表示哪些量？","options":[],"correct":"","answer":"教材称阻强，表示资源在网络链或转向处流动的阻力，可用时间、费用等表达；实际模型也可使用距离。求解时应明确量纲、方向和转向限制。参见教材 7.6.1，印刷第 194—195 页。"},{"id":"7-18","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"简答","question":"最短距离路径和最短时间路径为什么可能不同？","options":[],"correct":"","answer":"不同道路速度、拥堵、转向和通行限制不同，距离最短未必耗时最少。"},{"id":"7-19","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"简答","question":"什么是重分类？","options":[],"correct":"","answer":"依据规定阈值或规则，把原始数据值重新归并为新的类别或等级。"},{"id":"7-20","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"简答","question":"某河流缓冲区与居民地图层叠置可回答什么问题？","options":[],"correct":"","answer":"可筛选位于指定河流距离范围内的居民地，并进一步统计其数量或特征。"},{"id":"7-21","chapter":7,"chapterTitle":"第7章 GIS基本空间分析","type":"简答","question":"设施选址中为什么不能只依靠单一缓冲区？","options":[],"correct":"","answer":"还需考虑网络可达性、用地限制、需求分布、成本及数据精度等条件。"},{"id":"8-1","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"单项选择","question":"由高程变化率可以计算的地形因子是","options":["坡度","土地所有权","人口性别","道路名称"],"correct":"A","answer":"坡度刻画地表高程相对于水平距离的变化程度。"},{"id":"8-2","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"判断并说明","question":"DEM分辨率越高，就一定保证原始高程数据越准确。","options":[],"correct":"错误","answer":"错误。高程精度还取决于采样、数据来源和处理方法。"},{"id":"8-3","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"填空","question":"不规则三角网常用缩写________表示。","options":[],"correct":"","answer":"填空：TIN。"},{"id":"8-4","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"名词解释","question":"数字高程模型。","options":[],"correct":"","answer":"以数字形式表达地表高程及其空间分布的数据模型。"},{"id":"8-5","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"简答","question":"比较规则格网DEM与TIN。","options":[],"correct":"","answer":"格网结构规则、便于邻域和栅格运算；TIN以不规则三角形表达地形，可在地形变化复杂处加密，结构和运算较复杂。"},{"id":"8-6","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"应用与计算","question":"若两点高差为10米、水平距离为100米，求坡度角。","options":[],"correct":"","answer":"坡度角为 arctan(10/100)，约5.71度；百分比坡度为10%。"},{"id":"8-7","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"单项选择","question":"坡向通常用于描述","options":["坡面朝向","坡面高程唯一值","土地权属","人口总数"],"correct":"A","answer":"坡向表示坡面最大坡降方向，具体角度规则依软件定义。"},{"id":"8-8","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"单项选择","question":"格网DEM提取局部坡度通常需要","options":["周围邻域高程","地图标题","行政代码","图片文件名"],"correct":"A","answer":"通过邻域高程变化估计坡面梯度。"},{"id":"8-9","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"单项选择","question":"流域分析常用的基础数据是","options":["地形高程数据","字体文件","图例说明","照片日期"],"correct":"A","answer":"高程数据可支持流向、汇流和流域分析。"},{"id":"8-10","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"判断并说明","question":"等高线越密，通常表示该处地形越陡。","options":[],"correct":"正确","answer":"正确。在同一等高距和图幅条件下可作此判断。"},{"id":"8-11","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"判断并说明","question":"坡度为零的平坦区域一定具有明确坡向。","options":[],"correct":"错误","answer":"错误。完全平坦时最大坡降方向无法唯一确定。"},{"id":"8-12","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"判断并说明","question":"不同分辨率DEM可能产生不同的地形分析结果。","options":[],"correct":"正确","answer":"正确。分辨率会影响地形细节和邻域计算。"},{"id":"8-13","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"简答","question":"DEM和数字地形分析的关系是什么？","options":[],"correct":"","answer":"DEM提供地表高程的数字表达；数字地形分析基于DEM提取坡度、流域等地形信息。"},{"id":"8-14","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"简答","question":"建立DEM可使用哪些数据来源？","options":[],"correct":"","answer":"可利用等高线、高程点、实测数据或其他可靠高程数据，经处理和内插构建。"},{"id":"8-15","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"简答","question":"规则格网DEM的高程值如何定位？","options":[],"correct":"","answer":"由格网原点、行列号、像元大小及坐标参考确定位置，每个格网单元对应高程值。"},{"id":"8-16","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"简答","question":"说明坡度和坡向的区别。","options":[],"correct":"","answer":"坡度描述坡面倾斜程度；坡向描述坡面最大坡降的方向。"},{"id":"8-17","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"简答","question":"什么是地形插值？","options":[],"correct":"","answer":"根据已知高程样点及一定方法估计未知位置高程。"},{"id":"8-18","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"简答","question":"为什么地形突变处采样需要特别注意？","options":[],"correct":"","answer":"山脊、沟谷等关键地貌可能无法由稀疏或均匀采样充分表达，需要有代表性的点线约束。"},{"id":"8-19","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"简答","question":"流域提取的一般流程是什么？","options":[],"correct":"","answer":"检查DEM并按需要处理洼地；计算流向、汇流量；确定出口点；据流向划分汇水范围并核验。"},{"id":"8-20","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"简答","question":"视域分析受到哪些因素影响？","options":[],"correct":"","answer":"地形高程、观察点位置与高度、目标高度、分析范围以及DEM质量等。"},{"id":"8-21","chapter":8,"chapterTitle":"第8章 DEM与数字地形分析","type":"计算","question":"高差为20米、水平距离为200米，求百分比坡度。","options":[],"correct":"","answer":"20除以200乘100，得到10%。"},{"id":"9-1","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"单项选择","question":"用于研究相邻地区属性值相似或差异程度的方法是","options":["空间自相关分析","单纯文件压缩","扫描输入","地图折叠"],"correct":"A","answer":"空间自相关关注属性值与空间位置关系。"},{"id":"9-2","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"判断并说明","question":"普通相关系数可以完全代替考虑空间邻接关系的空间自相关指标。","options":[],"correct":"错误","answer":"错误。空间自相关显式考虑空间位置及空间权重。"},{"id":"9-3","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"填空","question":"利用已知采样点估计未知位置属性值的过程称为________。","options":[],"correct":"","answer":"填空：空间插值。"},{"id":"9-4","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"名词解释","question":"空间自相关。","options":[],"correct":"","answer":"空间现象的属性值与其空间位置关系之间存在的统计关联。"},{"id":"9-5","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"简答","question":"比较正空间自相关与负空间自相关。","options":[],"correct":"","answer":"正自相关表现为邻近单元数值相近的趋势；负自相关表现为邻近单元数值差异较大的趋势。结果受尺度和空间权重设定影响。"},{"id":"9-6","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"应用与计算","question":"用有限监测点估计区域降水分布，应考虑哪些因素？","options":[],"correct":"","answer":"检查点位和数据质量；选择合适坐标系、插值方法与参数；考虑空间分布及地形等影响；采用留出点或交叉验证评价误差。"},{"id":"9-7","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"单项选择","question":"以采样点估计未知位置数值属于","options":["空间插值","数据加密","地图装订","文字校对"],"correct":"A","answer":"空间插值使用已知观测估计未知位置。"},{"id":"9-8","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"单项选择","question":"研究事件点集中程度，可采用","options":["核密度分析","字体替换","光栅打印","表格排序"],"correct":"A","answer":"核密度可估计点事件的空间集聚分布。"},{"id":"9-9","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"单项选择","question":"空间自相关分析必须明确的重要条件之一是","options":["空间权重或邻接关系","文件封面颜色","论文页眉","打印纸尺寸"],"correct":"A","answer":"权重定义了哪些位置如何相互影响。"},{"id":"9-10","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"判断并说明","question":"全局空间自相关结果可以直接说明每个局部区域都具有同样的集聚模式。","options":[],"correct":"错误","answer":"错误。全局指标概括整体，局部差异需进一步分析。"},{"id":"9-11","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"判断并说明","question":"空间插值所得数值应视为估计值，而不是实测真值。","options":[],"correct":"正确","answer":"正确。估计误差取决于采样和方法。"},{"id":"9-12","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"判断并说明","question":"空间统计分析不需要考虑数据的位置。","options":[],"correct":"错误","answer":"错误。空间位置和关系是空间统计的重要组成。"},{"id":"9-13","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"简答","question":"什么是空间统计分析？","options":[],"correct":"","answer":"结合空间位置、空间关系与统计方法，描述和分析地理现象分布、关联及其变化的过程。"},{"id":"9-14","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"简答","question":"全局空间自相关与局部空间自相关有何区别？","options":[],"correct":"","answer":"前者概括整体空间关联；后者识别局部集聚、异常及其空间位置。"},{"id":"9-15","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"简答","question":"影响空间插值结果的因素有哪些？","options":[],"correct":"","answer":"采样数量与分布、测量质量、空间结构、插值方法和参数、边界与外部因素。"},{"id":"9-16","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"简答","question":"反距离权重插值的基本思路是什么？","options":[],"correct":"","answer":"以邻近已知点的加权值估计未知点，通常距离越近权重越大，具体由参数决定。"},{"id":"9-17","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"简答","question":"核密度图中的带宽会影响什么？","options":[],"correct":"","answer":"带宽影响平滑程度和集聚范围的表现；过大或过小都可能掩盖或夸大局部结构。"},{"id":"9-18","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"简答","question":"什么是空间权重矩阵？","options":[],"correct":"","answer":"用矩阵表示空间单元之间的邻接、距离或其他关系及其权重，为空间统计计算提供关系结构。"},{"id":"9-19","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"简答","question":"为什么分级方法会影响专题图解读？","options":[],"correct":"","answer":"不同分级边界会改变区域所属等级和视觉对比，从而影响对空间差异的判断。"},{"id":"9-20","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"简答","question":"空间统计中为什么要留意空间尺度？","options":[],"correct":"","answer":"观测单元大小、范围和聚合方式改变，统计关系及集聚结果也可能改变。"},{"id":"9-21","chapter":9,"chapterTitle":"第9章 GIS空间统计分析","type":"简答","question":"如何初步评价插值方法的可靠性？","options":[],"correct":"","answer":"采用独立验证点或交叉验证，比较预测误差，并结合点位分布和实际地理背景解释。"},{"id":"10-1","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"单项选择","question":"适合表示行政区统计指标空间差异的是","options":["分级设色专题图","文本编辑器设置","文件压缩包","数据库用户表"],"correct":"A","answer":"分级设色图可按分级将区域统计指标映射为视觉变量。"},{"id":"10-2","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"判断并说明","question":"地图颜色越多越鲜艳，信息表达一定越准确。","options":[],"correct":"错误","answer":"错误。颜色选择应匹配数据性质，保证可辨性并避免误导。"},{"id":"10-3","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"填空","question":"地图上对符号和颜色含义的解释通常通过________给出。","options":[],"correct":"","answer":"填空：图例。"},{"id":"10-4","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"名词解释","question":"地理信息可视化。","options":[],"correct":"","answer":"运用图形、符号和视觉表达方法呈现地理数据及其空间特征的过程。"},{"id":"10-5","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"简答","question":"制作专题地图应考虑哪些基本要素？","options":[],"correct":"","answer":"根据目的和数据选用合适投影、分类和符号；合理配置标题、图例、比例尺、方向、来源等；检查可读性和表达准确性。"},{"id":"10-6","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"应用与计算","question":"要比较各区人口密度，为什么通常不直接用人口总数绘制分级设色图？","options":[],"correct":"","answer":"行政区面积不同，总数不能直接反映单位面积集聚程度；应按人口除以面积计算密度，并检查分级与数据时点。"},{"id":"10-7","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"单项选择","question":"表示有序数量等级的颜色方案通常应","options":["体现有序明暗变化","随机指定互不相关颜色","全部使用相同颜色","不设置图例"],"correct":"A","answer":"有序视觉层次有助于表达数量大小。"},{"id":"10-8","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"单项选择","question":"地图图例的主要作用是","options":["解释符号和颜色含义","替代所有原始数据","改变坐标系统","消除空间误差"],"correct":"A","answer":"图例帮助读者解释地图符号。"},{"id":"10-9","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"单项选择","question":"按行政区显示人口密度时，首要关注","options":["统计时点和面积口径","文件名称","鼠标型号","图层顺序编号"],"correct":"A","answer":"人口与面积的时空口径会直接影响密度。"},{"id":"10-10","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"判断并说明","question":"同一种色阶适合所有定性和定量数据。","options":[],"correct":"错误","answer":"错误。色彩方案应符合类别、顺序或偏离中值等数据特性。"},{"id":"10-11","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"判断并说明","question":"地图符号和图例应保持一致。","options":[],"correct":"正确","answer":"正确。读者需要通过图例准确理解符号。"},{"id":"10-12","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"判断并说明","question":"三维显示产生的视觉效果可以自动保证地形分析精度。","options":[],"correct":"错误","answer":"错误。分析精度仍取决于数据及方法。"},{"id":"10-13","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"简答","question":"地理信息可视化的作用是什么？","options":[],"correct":"","answer":"将空间数据和分析结果转化为可感知的图形，支持探索、理解、交流和决策。"},{"id":"10-14","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"简答","question":"定性数据与定量数据的地图表达有什么区别？","options":[],"correct":"","answer":"定性数据强调类别区分；定量数据强调大小、顺序或差异程度，应采用相应视觉变量。"},{"id":"10-15","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"简答","question":"常用的视觉变量有哪些？","options":[],"correct":"","answer":"可包括位置、大小、形状、颜色、明度、纹理等；选用应与数据性质匹配。"},{"id":"10-16","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"简答","question":"分级设色图绘制的一般步骤是什么？","options":[],"correct":"","answer":"准备区域与统计数据；选择指标和分级方法；确定等级与配色；设置图例和必要地图要素；检验表达。"},{"id":"10-17","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"简答","question":"总量数据和强度数据在区域地图表达上有什么区别？","options":[],"correct":"","answer":"总量表示整体数量；强度或密度结合面积、人口等分母，适合表达相对水平，具体应按目的选择。"},{"id":"10-18","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"简答","question":"为什么要在地图中标明数据来源和时间？","options":[],"correct":"","answer":"便于判断数据可靠性、现势性及不同数据之间的可比性。"},{"id":"10-19","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"简答","question":"地图注记编排应注意什么？","options":[],"correct":"","answer":"保持文字清晰、层次合理，尽量避免遮挡重要要素和互相重叠。"},{"id":"10-20","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"简答","question":"地形晕渲的作用和局限是什么？","options":[],"correct":"","answer":"通过模拟光照突出地形起伏；视觉效果受光源方向影响，不能单独替代定量高程信息。"},{"id":"10-21","chapter":10,"chapterTitle":"第10章 地理信息可视化","type":"简答","question":"三维地形可视化中的高程夸大会带来什么影响？","options":[],"correct":"","answer":"可以增强起伏的视觉辨识，但可能改变对真实坡度和地貌形态的直观判断，应说明夸大比例。"},{"id":"11-1","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"单项选择","question":"用户主要通过浏览器访问系统，通常属于","options":["B/S模式","仅离线纸质地图","单机无网络模式","打印模式"],"correct":"A","answer":"B/S模式中浏览器作为客户端，通过网络访问服务器提供的功能和数据。"},{"id":"11-2","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"判断并说明","question":"B/S模式不需要服务器或网络通信。","options":[],"correct":"错误","answer":"错误。浏览器通常需要通过网络与服务器交互。"},{"id":"11-3","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"填空","question":"浏览器／服务器体系结构常简称为________。","options":[],"correct":"","answer":"填空：B/S。"},{"id":"11-4","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"名词解释","question":"网络GIS。","options":[],"correct":"","answer":"依托计算机网络实现地理信息数据、功能或服务共享与协同应用的地理信息系统。"},{"id":"11-5","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"简答","question":"比较C/S和B/S模式。","options":[],"correct":"","answer":"C/S使用专门客户端，客户端功能可较丰富但部署维护涉及各终端；B/S通过浏览器访问，部署更新相对集中，但受网络和浏览器能力影响。"},{"id":"11-6","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"应用与计算","question":"设计在线校园地图服务，说明主要组成与基本流程。","options":[],"correct":"","answer":"采集并管理校园空间数据；服务器提供地图和查询服务；浏览器请求并呈现；考虑权限、数据更新及可用性。"},{"id":"11-7","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"单项选择","question":"Web GIS中客户端和服务端之间的基础联系依赖","options":["网络通信","打印机墨盒","键盘布局","扫描分辨率"],"correct":"A","answer":"客户端通过网络请求服务端数据或功能。"},{"id":"11-8","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"单项选择","question":"在线地图的地图服务主要用于","options":["发布和提供地图显示及相关能力","代替全部原始测量","消除数据更新需求","自动证明数据正确"],"correct":"A","answer":"地图服务向客户端提供地图及相关访问能力。"},{"id":"11-9","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"单项选择","question":"不同系统交换地理信息时，为提高互操作性应关注","options":["统一接口与数据规范","文件夹颜色","屏幕尺寸","鼠标灵敏度"],"correct":"A","answer":"共同遵循接口和数据规范有利于互操作。"},{"id":"11-10","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"判断并说明","question":"网络GIS可以通过网络共享数据和分析功能。","options":[],"correct":"正确","answer":"正确。具体能力由系统设计和服务实现决定。"},{"id":"11-11","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"判断并说明","question":"服务器集中更新意味着完全不需要考虑数据安全和访问权限。","options":[],"correct":"错误","answer":"错误。集中部署仍需权限、备份和安全维护。"},{"id":"11-12","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"判断并说明","question":"移动GIS可结合移动终端位置开展应用。","options":[],"correct":"正确","answer":"正确。可在具备相应定位和网络条件下提供位置相关功能。"},{"id":"11-13","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"简答","question":"网络GIS的一般组成是什么？","options":[],"correct":"","answer":"通常包括客户端、网络、服务端及地理空间数据，具体实现随体系结构而异。"},{"id":"11-14","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"简答","question":"地理信息服务的基本思想是什么？","options":[],"correct":"","answer":"将地理数据或功能通过明确的接口提供给网络用户或其他系统使用。"},{"id":"11-15","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"简答","question":"C/S模式中的客户端承担什么角色？","options":[],"correct":"","answer":"专用客户端可承担界面展示、部分处理或业务逻辑，具体分工由系统架构决定。"},{"id":"11-16","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"简答","question":"B/S模式为什么便于集中维护？","options":[],"correct":"","answer":"主要服务和业务更新可在服务器侧完成，用户通常通过浏览器访问，减少逐台安装工作。"},{"id":"11-17","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"简答","question":"什么是互操作性？","options":[],"correct":"","answer":"不同系统能够按约定交换和使用信息与功能的能力。"},{"id":"11-18","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"简答","question":"移动GIS与传统固定终端GIS相比增加了哪些考虑？","options":[],"correct":"","answer":"需考虑移动定位、网络条件、终端性能、现场采集、离线同步及设备供电等。"},{"id":"11-19","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"简答","question":"地图瓦片有什么用途？","options":[],"correct":"","answer":"将地图按分级和网格切分，客户端按需请求，有助于提高浏览和缓存效率。"},{"id":"11-20","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"简答","question":"网络GIS项目为什么需要数据更新机制？","options":[],"correct":"","answer":"地物与业务会变化，更新与版本管理可减少过时信息并支持成果追溯。"},{"id":"11-21","chapter":11,"chapterTitle":"第11章 网络GIS与地理信息服务","type":"简答","question":"开放地图服务时应考虑什么？","options":[],"correct":"","answer":"明确数据授权、访问权限、服务性能、更新维护以及数据准确性和适用范围。"}];
